+package server
+
+import (
+	"encoding/json"
+	"net/http"
+	"strings"
+
+	"golang.org/x/crypto/bcrypt"
+
+	"git.aisoftwarefactory.world/linkshort4/linkshort4/internal/session"
+)
+
+func handleSignup(w http.ResponseWriter, r *http.Request, db interface {
+	CreateUser(ctx interface{}, email, passwordHash string) (interface{ GetID() string; GetEmail() string }, error)
+}) {
+	var req struct {
+		Email    string `json:"email"`
+		Password string `json:"password"`
+	}
+	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request"})
+		return
+	}
+	if !isValidEmail(req.Email) || len(req.Password) < 10 {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid email or password too short"})
+		return
+	}
+	hash, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
+	if err != nil {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	s, ok := StoreFromContext(r.Context())
+	if !ok {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	user, err := s.CreateUser(r.Context(), req.Email, string(hash))
+	if err != nil {
+		writeJSON(w, http.StatusConflict, map[string]string{"error": "email already registered"})
+		return
+	}
+	sess, err := s.CreateSession(r.Context(), user.ID)
+	if err != nil {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	session.SetCookie(w, r, sess.ID)
+	writeJSON(w, http.StatusCreated, map[string]string{"id": user.ID, "email": user.Email})
+}
+
+func handleLogin(w http.ResponseWriter, r *http.Request) {
+	var req struct {
+		Email    string `json:"email"`
+		Password string `json:"password"`
+	}
+	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request"})
+		return
+	}
+	if !isValidEmail(req.Email) || len(req.Password) < 10 {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid email or password too short"})
+		return
+	}
+	s, ok := StoreFromContext(r.Context())
+	if !ok {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	user, err := s.GetUserByEmail(r.Context(), req.Email)
+	if err != nil {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
+		return
+	}
+	if err := bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(req.Password)); err != nil {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
+		return
+	}
+	sess, err := s.CreateSession(r.Context(), user.ID)
+	if err != nil {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	session.SetCookie(w, r, sess.ID)
+	writeJSON(w, http.StatusOK, map[string]string{"id": user.ID, "email": user.Email})
+}
+
+func handleLogout(w http.ResponseWriter, r *http.Request) {
+	sid := session.GetSessionID(r)
+	if sid != "" {
+		s, ok := StoreFromContext(r.Context())
+		if ok {
+			_ = s.DeleteSession(r.Context(), sid)
+		}
+	}
+	session.ClearCookie(w, r)
+	w.WriteHeader(http.StatusNoContent)
+}
+
+func handleMe(w http.ResponseWriter, r *http.Request) {
+	userID, ok := session.UserID(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	s, ok := StoreFromContext(r.Context())
+	if !ok {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	user, err := s.GetUserByID(r.Context(), userID)
+	if err != nil {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	writeJSON(w, http.StatusOK, map[string]string{"id": user.ID, "email": user.Email})
+}
+
+func isValidEmail(email string) bool {
+	if email == "" {
+		return false
+	}
+	at := strings.Index(email, "@")
+	if at < 1 {
+		return false
+	}
+	domain := email[at+1:]
+	if len(domain) < 3 || !strings.Contains(domain, ".") {
+		return false
+	}
+	return true
+}

